from datetime import datetime
import pytz

Remote = self.remote_id
Sensor = env['mdm.measurement.device.sensor']
Reading = env['mdm.measurement.device.sensor.reading']
today_str = fields.Date.today()
condition = [
    ('remotecontrol_params','!=',False),
    ('device_id.remotecontrol_id', '=', Remote.id)
]
if selected_device_ids:
    condition.append(('device_id', 'in', selected_device_ids))
sensors = Sensor.search(condition)
# Optimize: build map of sensor_id -> most recent reading (single query)
last_readings_map = {}
if sensors:
    sensor_ids = [s.id for s in sensors]
    cr = env.cr
    cr.execute(
        'SELECT DISTINCT ON (sensor_id) sensor_id, measurement_time '
        'FROM mdm_measurement_device_sensor_reading '
        'WHERE sensor_id IN %s AND active = TRUE '
        'ORDER BY sensor_id, measurement_time DESC',
        (tuple(sensor_ids),)
    )
    for row in cr.fetchall():
        last_readings_map[row[0]] = row[1]
# Now iterate sensors using the map
plan = []
for sensor in sensors:
    device = sensor.device_id
    try:
        sensor_cfg = json.loads(sensor.remotecontrol_params or '{}') or {}
    except Exception:
        sensor_cfg = {}
    sensor_id_value = sensor_cfg.get('id')
    if isinstance(sensor_id_value, int):
        try:
            device_cfg = json.loads(device.remotecontrol_params or '{}') or {}
        except Exception:
            device_cfg = {}
        # Retrieve last_reading from map (no query per sensor)
        last_reading_time = last_readings_map.get(sensor.id)
        if last_reading_time:
            try:
                last_dt = (last_reading_time if isinstance(last_reading_time, datetime)
                           else fields.Datetime.from_string(last_reading_time))
                last_dt = pytz.UTC.localize(last_dt).astimezone(
                    pytz.timezone('Europe/Madrid'))
                start_date = last_dt.strftime('%Y-%m-%d %H:%M:%S')
            except Exception:
                start_date = str(last_reading_time)
        else:
            start_cfg = device_cfg.get('start_date')
            if start_cfg:
                s = start_cfg.strip().replace('/', '-')
                if len(s) == 10:
                    s = s + ' 00:00:00'
                try:
                    dt_cfg = datetime.strptime(s, '%Y-%m-%d %H:%M:%S')
                    start_date = dt_cfg.strftime('%Y-%m-%d %H:%M:%S')
                except Exception:
                    start_date = s
            else:
                year_str = today_str[:4]
                s2 = '%s-01-01 00:00:00' % year_str
                try:
                    dt_y = datetime.strptime(s2, '%Y-%m-%d %H:%M:%S')
                    start_date = dt_y.strftime('%Y-%m-%d %H:%M:%S')
                except Exception:
                    start_date = s2
        plan.append({
            'sensor_id': sensor.id,
            'device_id': device.id,
            'sensor_id_value': sensor_id_value,
            'start_date': str(start_date),
        })
bag['sensors_plan'] = plan

from datetime import datetime, timedelta import pytz import hashlib import math
Remote = self.remote_id plan = bag.get('sensors_plan') or [] cfg = json.loads(Remote.connection_params or '{}') or {} username = (cfg.get('username') or '').strip() password = (cfg.get('password') or '').strip() if not username or not password: raise Exception('Missing credentials: configure username/password') password_md5 = hashlib.md5(password.encode('utf-8')).hexdigest() url = Remote.base_url.rstrip('/') + '/apirest' headers = {'Content-Type': 'application/json', 'Accept': 'application/json'}
# Shared quota control for workers in the same database. import requests import time
def salz_request(payload, attempts=None): attempts = attempts if attempts is not None else [] quota = '%s|%s|%s' % ( url.rstrip('/').lower(), username.lower(), payload['comando']) lock_id = int(hashlib.sha256(quota.encode('utf-8')).hexdigest()[:15], 16) retries = min(2, max(0, int(self.max_retries or 0))) with env.registry.cursor() as quota_cr: quota_cr.execute('SELECT pg_advisory_xact_lock(%s)', (lock_id,)) for attempt in range(retries + 1): detail = {'attempt': attempt + 1, 'started_at': fields.Datetime.now()} attempts.append(detail) try: response = requests.request( 'POST', url, headers=headers, json=payload, timeout=Remote.timeout or 60, verify=Remote.verify_ssl, allow_redirects=False) except requests.RequestException as exc: detail['network_error'] = type(exc).__name__ if attempt >= retries: raise continue finally: # No hidden retries. Keep the lock through every cooldown. time.sleep(3.1) detail['status'] = response.status_code try: body = response.json() except ValueError: body = {} api_code = body.get('codError') if isinstance(body, dict) else None detail['codError'] = api_code limited = response.status_code == 429 or str(api_code) == '19' transient = response.status_code >= 500 if (limited or transient) and attempt < retries: delay = 61.0 try: delay = max(delay, float(response.headers.get('Retry-After', 0))) except (TypeError, ValueError): pass if delay > 300: detail['retry_deferred'] = True return response detail['retry_wait_seconds'] = delay # Holding the shared lock prevents another local worker # from consuming this command's quota during recovery. remaining = delay while remaining > 0: pause = min(remaining, 30.0) time.sleep(pause) remaining -= pause continue return response
def parse_date(value): value = unicode(value).strip().replace('/', '-') if len(value) == 10: value += ' 00:00:00' return datetime.strptime(value, '%Y-%m-%d %H:%M:%S')
def error_text(exc): try: return unicode(exc) except Exception: return str(exc).decode('utf-8', 'replace')
tz_madrid = pytz.timezone('Europe/Madrid') end = datetime.now(pytz.UTC).astimezone(tz_madrid).replace(tzinfo=None, microsecond=0) total_upserts = 0 total_errors = 0 items = [] pending = [] for entry in plan: try: sensor = dict(entry) sensor['cursor'] = parse_date(sensor['start_date']) if sensor['cursor'] < end: pending.append(sensor) except Exception as exc: total_errors += 1 items.append({'sensor_id': entry.get('sensor_id'), 'error': error_text(exc)})
while pending: start = min(s['cursor'] for s in pending) finish = min(start + timedelta(days=28), end) batch = [s for s in pending if s['cursor'] < finish] variables = sorted(set(s['sensor_id_value'] for s in batch)) payload = { 'comando': 'consultaHistoricos', 'correo': username, 'contrasenya': password_md5, 'variables': variables, 'fechaIni': start.strftime('%Y-%m-%d %H:%M:%S'), 'fechaFin': finish.strftime('%Y-%m-%d %H:%M:%S'), } request_item = { 'fechaIni': payload['fechaIni'], 'fechaFin': payload['fechaFin'], 'variables': variables, 'sensors': [], 'attempts': [], } items.append(request_item) try: resp = salz_request(payload, request_item['attempts']) request_item['status'] = resp.status_code if not 200 <= resp.status_code < 300: raise Exception('HTTP %s from consultaHistoricos' % resp.status_code) data = resp.json() request_item['codError'] = data.get('codError', -1) if str(data.get('codError')) != '0': raise Exception('API codError=%s: %s' % ( data.get('codError'), data.get('error', ''))) historicos = data.get('historicos') if not isinstance(historicos, dict): raise Exception('Invalid historicos response') except Exception as exc: request_item['error'] = error_text(exc) if (request_item.get('status') == 429 or str(request_item.get('codError')) == '19'): request_item['stopped_reason'] = 'rate_limit_exhausted' request_item['pending_sensor_ids'] = [s['sensor_id'] for s in pending] total_errors += len(pending) # A command-wide rejection must not trigger more batches. break total_errors += len(batch) # Never advance affected sensors past a failed interval. pending = [s for s in pending if s not in batch] continue for sensor in batch: result = {'sensor_id': sensor['sensor_id'], 'sensor_id_value': sensor['sensor_id_value'], 'upserts': 0} request_item['sensors'].append(result) try: variable = str(sensor['sensor_id_value']) if variable not in historicos: raise Exception('Variable missing from historicos: %s' % variable) values = historicos[variable] if not isinstance(values, list): raise Exception('Invalid readings list: %s' % variable) points = [] for value in values: stamp = parse_date(value['fecha']) number = float(value['valor']) if math.isnan(number) or math.isinf(number): raise Exception('Non-finite reading') if stamp < sensor['cursor']: continue if stamp > finish: raise Exception('Reading outside requested interval') utc = tz_madrid.localize(stamp).astimezone(pytz.UTC) points.append((utc.strftime('%Y-%m-%d %H:%M:%S'), number)) # Atomic sensor/window: a failed create must not leave newer # readings that would hide a gap on the next execution. with env.cr.savepoint(): for stamp, number in sorted(points): Remote.upsert( 'mdm.measurement.device.sensor.reading', {'sensor_id': sensor['sensor_id'], 'measurement_time': stamp}, {'value': number, 'remotecontrol_origin_id': Remote.id}) result['upserts'] = len(points) total_upserts += len(points) sensor['cursor'] = finish if finish == end: pending.remove(sensor) except Exception as exc: result['error'] = error_text(exc) total_errors += 1 pending.remove(sensor) audit = { 'integration_version': '10.0.1.0.8', 'executed_at': fields.Datetime.now(), 'total_upserts': total_upserts, 'total_errors': total_errors, 'items': items, } try: audit_json = json.dumps(audit, ensure_ascii=True, indent=2, default=str) b64 = base64.b64encode(audit_json.encode('utf-8')) except Exception as json_error: simple_audit = { 'executed_at': str(fields.Datetime.now()), 'total_upserts': total_upserts, 'total_errors': total_errors, 'error': str(json_error), } audit_json = json.dumps(simple_audit, ensure_ascii=True, indent=2) b64 = base64.b64encode(audit_json.encode('utf-8')) fname = 'readings_riegosalz_%s.json' % fields.Datetime.now().replace(':', '').replace('-', '').replace(' ', '_') att = env['ir.attachment'].create({ 'name': fname, 'datas_fname': fname, 'datas': b64, 'mimetype': 'application/json', 'res_model': 'remotecontrol', 'res_id': Remote.id, }) Remote.message_post( body=u"[RiegosSalz] upserts=%s errors=%s" % (total_upserts, total_errors), attachment_ids=[att.id] ) bag['upserts'] = total_upserts bag['errors'] = total_errors bag['audit_attachment_id'] = att.id

import hashlib

Remote = self.remote_id
base_url = Remote.base_url
cfg = {}
try:
    cfg = json.loads(Remote.connection_params or '{}') or {}
except Exception:
    cfg = {}
username = (cfg.get('username') or '').strip()
password = (cfg.get('password') or '').strip()
if not username or not password:
    raise Exception(
        "Missing credentials: please configure username/password "
        "in connection_params"
    )
password_md5 = hashlib.md5(password.encode('utf-8')).hexdigest()
url = base_url.rstrip('/') + '/apirest'
headers = {
    'Content-Type': 'application/json',
    'Accept': 'application/json',
}

# Shared quota control for workers in the same database.
import requests
import time

def salz_request(payload, attempts=None):
    attempts = attempts if attempts is not None else []
    quota = '%s|%s|%s' % (
        url.rstrip('/').lower(), username.lower(), payload['comando'])
    lock_id = int(hashlib.sha256(quota.encode('utf-8')).hexdigest()[:15], 16)
    retries = min(2, max(0, int(self.max_retries or 0)))
    with env.registry.cursor() as quota_cr:
        quota_cr.execute('SELECT pg_advisory_xact_lock(%s)', (lock_id,))
        for attempt in range(retries + 1):
            detail = {'attempt': attempt + 1, 'started_at': fields.Datetime.now()}
            attempts.append(detail)
            try:
                response = requests.request(
                    'POST', url, headers=headers, json=payload,
                    timeout=Remote.timeout or 60,
                    verify=Remote.verify_ssl, allow_redirects=False)
            except requests.RequestException as exc:
                detail['network_error'] = type(exc).__name__
                if attempt >= retries:
                    raise
                continue
            finally:
                # No hidden retries. Keep the lock through every cooldown.
                time.sleep(3.1)
            detail['status'] = response.status_code
            try:
                body = response.json()
            except ValueError:
                body = {}
            api_code = body.get('codError') if isinstance(body, dict) else None
            detail['codError'] = api_code
            limited = response.status_code == 429 or str(api_code) == '19'
            transient = response.status_code >= 500
            if (limited or transient) and attempt < retries:
                delay = 61.0
                try:
                    delay = max(delay, float(response.headers.get('Retry-After', 0)))
                except (TypeError, ValueError):
                    pass
                if delay > 300:
                    detail['retry_deferred'] = True
                    return response
                detail['retry_wait_seconds'] = delay
                # Holding the shared lock prevents another local worker
                # from consuming this command's quota during recovery.
                remaining = delay
                while remaining > 0:
                    pause = min(remaining, 30.0)
                    time.sleep(pause)
                    remaining -= pause
                continue
            return response

payload = {
    'comando': 'consultaRemotas',
    'correo': username,
    'contrasenya': password_md5,
}
request_attempts = []
resp = salz_request(payload, request_attempts)
code = resp.status_code
if not 200 <= code < 300:
    raise Exception(
        "HTTP %s from consultaRemotas: %s" % (code, (resp.text or '')[:500])
    )
data = resp.json() or {}
cod_error = data.get('codError', -1)
if str(cod_error) != '0':
    error_msg = data.get('error', '')
    if isinstance(error_msg, list):
        error_msg = '; '.join(error_msg)
    raise Exception(
        "API codError=%s: %s" % (cod_error, error_msg)
    )
remotas_raw = data.get('remotas', {}) or {}
elements = []
for remota_key, remota in remotas_raw.items():
    id_remota = remota.get('id_remota')
    descripcion_remota = remota.get('descripcion', '')
    placas_raw = remota.get('placas', {}) or {}
    placas = []
    for placa_key, placa in placas_raw.items():
        id_placa = placa.get('id_placa')
        descripcion_placa = placa.get('descripcion', '')
        numero_placa = placa.get('numero', '')
        variables_raw = placa.get('placa_variables', {}) or {}
        variables = []
        for var_key, var in variables_raw.items():
            variables.append({
                'id_placavariable': var.get('id_placavariable'),
                'descripcion': var.get('descripcion', ''),
                'valor': var.get('valor', ''),
                'unidades': var.get('unidades', ''),
                'decimales': var.get('decimales', ''),
                'magnitud': var.get('magnitud', ''),
            })
        acciones_raw = placa.get('placa_acciones', {}) or {}
        acciones = []
        for acc_key, acc in acciones_raw.items():
            acciones.append({
                'codigo': acc.get('codigo', ''),
                'descripcion': acc.get('descripcion', ''),
            })
        placas.append({
            'id_placa': id_placa,
            'numero': numero_placa,
            'descripcion': descripcion_placa,
            'variables': variables,
            'acciones': acciones,
        })
    elements.append({
        'id_remota': id_remota,
        'descripcion': descripcion_remota,
        'placas': placas,
    })
# Build flat sensor config table for easy reference
sensor_config_table = []
for el in elements:
    for placa in el.get('placas', []):
        for var in placa.get('variables', []):
            sensor_config_table.append({
                'remota': el.get('descripcion', ''),
                'id_remota': el.get('id_remota'),
                'placa': placa.get('descripcion', ''),
                'id_placa': placa.get('id_placa'),
                'variable': var.get('descripcion', ''),
                'id_placavariable': var.get('id_placavariable'),
                'unidades': var.get('unidades', ''),
                'magnitud': var.get('magnitud', ''),
                'valor_actual': var.get('valor', ''),
                'decimales': var.get('decimales', ''),
                'odoo_device_params': json.dumps(
                    {'start_date': fields.Date.today()},
                    ensure_ascii=True,
                ),
                'odoo_sensor_params': json.dumps(
                    {'id': var.get('id_placavariable')},
                    ensure_ascii=True,
                ),
            })
audit = {
    'executed_at': fields.Datetime.now(),
    'integration_version': '10.0.1.0.8',
    'attempts': request_attempts,
    'total_remotas': len(elements),
    'total_variables': len(sensor_config_table),
    'elements': elements,
    'sensor_config_table': sensor_config_table,
}
try:
    audit_json = json.dumps(
        audit, ensure_ascii=True, indent=2, default=str,
    )
    b64 = base64.b64encode(audit_json.encode('utf-8'))
except Exception as json_error:
    simple_audit = {
        'executed_at': str(fields.Datetime.now()),
        'error': str(json_error),
    }
    audit_json = json.dumps(simple_audit, ensure_ascii=True, indent=2)
    b64 = base64.b64encode(audit_json.encode('utf-8'))
fname = 'riegosalz_elements_%s.json' % (
    fields.Datetime.now()
    .replace(':', '')
    .replace('-', '')
    .replace(' ', '_')
)
att = env['ir.attachment'].create({
    'name': fname,
    'datas_fname': fname,
    'datas': b64,
    'mimetype': 'application/json',
    'res_model': 'remotecontrol',
    'res_id': Remote.id,
})
Remote.message_post(
    body=u"[RiegosSalz] consultaRemotas: %s remotas, %s variables"
         % (len(elements), len(sensor_config_table)),
    attachment_ids=[att.id],
)
